ALTER TABLE "portable_record_access_events" ADD CONSTRAINT "record_access_action" CHECK (("portable_record_access_events"."action" IN ('detail','list','csv','integration','search','report','related','history') OR ("portable_record_access_events"."action" IN ('duplicates','merge_preview') AND "portable_record_access_events"."kind" IN ('contacts','companies')) OR ("portable_record_access_events"."action"='document' AND "portable_record_access_events"."kind" IN ('contacts','quotes','invoices'))) AND (("portable_record_access_events"."token_id" IS NOT NULL) = ("portable_record_access_events"."action"='integration')));